from pathlib import Path
import json, sys
ROOT=Path(__file__).resolve().parents[1]
def check(ok,label):
    if not ok:
        print('FAIL - '+label);sys.exit(1)
    print('PASS - '+label)
main=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
php=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
reg=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
js=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.21.0.js').read_text()
css=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.21.0.css').read_text()
manifest=json.loads((ROOT/'release-manifest-v0.21.0.json').read_text())
record=json.loads((ROOT/'registry/workspace-product-record-v0.21.0.json').read_text())
check('Version: 0.21.0' in main,'plugin version')
check("define('SC_WORKSPACE_VERSION', '0.21.0')" in main,'runtime version')
check(manifest['version']=='0.21.0' and manifest['previous_version']=='0.20.0','manifest release lineage')
check(manifest['release_name']=='Accounts & Cloud Persistence Foundation','release name')
check(manifest['storage_schema_version']==21 and manifest['project_schema']=='sc-workspace-project/11.0','storage 21 / project schema stable')
check(manifest.get('schema_migration_required') is True,'workspace-level storage migration declared')
check("'/account-persistence-contract'" in php and 'public function account_persistence_contract()' in php,'account persistence REST contract')
check("'/cloud-projects'" in php and 'cloud_project_store' in php and 'cloud_project_get' in php and 'cloud_project_delete' in php,'manual cloud project REST endpoints')
check("is_user_logged_in() && current_user_can('read')" in php,'authenticated cloud permission boundary')
check("get_user_meta(get_current_user_id()" in php and "update_user_meta(get_current_user_id()" in php,'per-user server storage')
check("hash('sha256', $canonical)" in php,'server SHA-256 fingerprint')
check("const ACCOUNT_PERSISTENCE_SCHEMA = 'sc-workspace-account-persistence/1.0'" in js,'account persistence schema')
check("const CLOUD_BACKUP_SCHEMA = 'sc-workspace-cloud-backup/1.0'" in js,'cloud backup schema')
check('const STORAGE_VERSION = 21;' in js and 'function migrateV20(raw)' in js,'storage 20 to 21 migration')
check("const PROJECT_SCHEMA = 'sc-workspace-project/11.0'" in js,'project schema unchanged')
check('data-scw-cloud-backup' in php and 'data-scw-cloud-refresh' in php and 'data-scw-cloud-list' in php,'manual cloud recovery UI')
check("'X-WP-Nonce'" in js and 'credentials: \'same-origin\'' in js,'WordPress REST nonce and same-origin credentials')
check("copy=cloneProject(source)" in js and "(Recovered)" in js,'restore-as-new-local-copy')
check(manifest['account_persistence']['manual_backup'] and not manifest['account_persistence']['automatic_upload'] and not manifest['account_persistence']['background_sync'],'manual not automatic cloud boundary')
check(manifest['account_persistence']['restore_mode']=='new-local-copy' and not manifest['governance']['cloud_restore_overwrites_local_project'],'restore overwrite prohibited')
check(manifest['account_persistence']['max_projects_per_account']==25 and manifest['account_persistence']['max_project_bytes']==2621440 and manifest['account_persistence']['max_account_bytes']==26214400,'cloud storage guardrails')
check(manifest['anonymous_access'] and not manifest['account_required'],'guest Workspace remains first-class')
check(manifest['cloud_sync'] is False and manifest['server_project_storage']=='manual-account-backup-only','cloud persistence scope explicit')
check(manifest['governance']['team_cloud_storage'] is False,'no team cloud storage')
check("const LAST_GOOD_KEY = 'sc_workspace_last_good_v1'" in js and 'function captureLastGoodSnapshot()' in js,'v0.20 local recovery preserved')
check('sc-workspace-diagnostic-report/1.0' in js and 'sc-workspace-emergency-backup/1.0' in js,'v0.20 diagnostics and emergency backup preserved')
check('@media(prefers-reduced-motion:reduce)' in css and '@media(forced-colors:active)' in css and ':focus-visible' in css,'accessibility hardening preserved')
check(manifest['readiness']['accessibility_target']=='WCAG 2.2 AA','WCAG 2.2 AA target preserved')
check(manifest['canonical_library_path']=='/knowledge-libraries/' and '/knowledge-libraries/' in php,'canonical Knowledge Library route')
check(record['public_version']=='0.21.0' and record['previous_version']=='0.20.0','registry record lineage')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0210'" in reg and "LEGACY_PENDING_KEY_V0200 = 'sc_workspace_registry_pending_v0200'" in reg,'registry pending/backup lineage')
check((ROOT/'history/release-manifest-v0.20.0.json').exists() and (ROOT/'history/workspace-product-record-v0.20.0.json').exists(),'v0.20.0 history preserved')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.21.0 — Accounts & Cloud Persistence Foundation')
